def add_sample_products(apps, schema_editor):
    supplier_model = apps.get_model('warehouse', 'NhaCungCap')
    product_model = apps.get_model('warehouse', 'HangHoa')
    unit_model = apps.get_model('warehouse', 'DonViTinh')
    database = schema_editor.connection.alias
    units = {
        unit.ten_dvt: unit.pk
        for unit in unit_model.objects.using(database).all()
    }

    for supplier_code, products in SAMPLE_PRODUCTS.items():
        supplier = supplier_model.objects.using(database).filter(
            ma_ncc=supplier_code
        ).first()
        if supplier is None:
            continue

        for product_code, product_name, unit_name in products:
            product, _ = product_model.objects.using(database).get_or_create(
                ma_hang=product_code,
                defaults={
                    'ten_hang': product_name,
                    'don_vi_tinh_id': units.get(unit_name),
                    'so_luong_ton': 0,
                    'ton_toi_thieu': 5,
                    'gia_nhap': 0,
                    'gia_xuat': 0,
                },
            )
            supplier.hang_hoa.add(product)

    coca_cola_supplier = supplier_model.objects.using(database).filter(
        ma_ncc='NCC01'
    ).first()
    existing_coca_cola = product_model.objects.using(database).filter(
        ma_hang='SH12'
    ).first()
    if coca_cola_supplier and existing_coca_cola:
        coca_cola_supplier.hang_hoa.add(existing_coca_cola)


